import java.util.*;

class Solution {
    public int maxLevelSum(TreeNode root) {
        if (root == null) return 0;
        Queue<TreeNode> q = new ArrayDeque<>();
        q.offer(root);
        int maxSum = Integer.MIN_VALUE;
        int bestLevel = 1, level = 1;

        while (!q.isEmpty()) {
            int sz = q.size();
            int currSum = 0;
            for (int i = 0; i < sz; i++) {
                TreeNode node = q.poll();
                currSum += node.val;
                if (node.left != null) q.offer(node.left);
                if (node.right != null) q.offer(node.right);
            }
            if (currSum > maxSum) {
                maxSum = currSum;
                bestLevel = level;
            }
            level++;
        }
        return bestLevel;
    }
}

var maxLevelSum = function(root) {
    if (!root) return 0;
    let q = [root];
    let maxSum = -Infinity;
    let bestLevel = 1, level = 1;

    while (q.length > 0) {
        let currSum = 0;
        const nextQ = [];
        for (const node of q) {
            currSum += node.val;
            if (node.left) nextQ.push(node.left);
            if (node.right) nextQ.push(node.right);
        }
        if (currSum > maxSum) {
            maxSum = currSum;
            bestLevel = level;
        }
        q = nextQ;
        level++;
    }
    return bestLevel;
};
